import assert from 'node:assert/strict';
import * as fs from 'node:fs/promises';
import path from 'node:path';

import {
  removeResolvedApp,
  setResolvedAppAssignedPort,
  setResolvedAppEnabled,
  writeAppsResolutionFile,
  writeAppsResolutionFileIfChanged,
} from '../main/apps/resolution-file';
import { readAppResolution, resolvedApp, writeLocalApp } from './helpers/app-fixture';
import { withTempRtws } from './kernel-driver/helpers';

async function main(): Promise<void> {
  await withTempRtws(async (rtws) => {
    const one = resolvedApp(
      await writeLocalApp(path.join(rtws, 'packages', 'one'), 'one', { defaultPort: 43001 }),
      43001,
    );
    const other = resolvedApp(await writeLocalApp(path.join(rtws, 'packages', 'other'), 'other'));
    const file = { schemaVersion: 1 as const, apps: [one, other] };
    const original = structuredClone(file);
    await writeAppsResolutionFile({ rtwsRootAbs: rtws, file });
    const target = path.join(rtws, '.apps', 'resolution.yaml');
    await fs.utimes(target, new Date('2000-01-01T00:00:00Z'), new Date('2000-01-01T00:00:00Z'));
    const bytes = await fs.readFile(target);
    const before = await fs.stat(target);
    for (const next of [
      setResolvedAppEnabled({ existing: file, appId: 'missing', enabled: false }),
      setResolvedAppEnabled({ existing: file, appId: 'one', enabled: true }),
      setResolvedAppAssignedPort({ existing: file, appId: 'missing', assignedPort: 50000 }),
      setResolvedAppAssignedPort({ existing: file, appId: 'one', assignedPort: 43001 }),
      removeResolvedApp({ existing: file, appId: 'missing' }),
    ]) {
      assert.deepEqual(next, original);
      await writeAppsResolutionFileIfChanged({ rtwsRootAbs: rtws, file: next });
      assert.deepEqual(await fs.readFile(target), bytes);
      assert.equal((await fs.stat(target)).mtimeMs, before.mtimeMs);
    }
    const changed = setResolvedAppAssignedPort({
      existing: file,
      appId: 'one',
      assignedPort: 43002,
    });
    await writeAppsResolutionFileIfChanged({ rtwsRootAbs: rtws, file: changed });
    const persisted = await readAppResolution(rtws);
    assert.deepEqual(
      persisted.apps.find((entry) => entry.id === 'one'),
      { ...one, assignedPort: 43002 },
    );
    assert.deepEqual(
      persisted.apps.find((entry) => entry.id === 'other'),
      other,
    );
    assert.notDeepEqual(await fs.readFile(target), bytes);
    assert.notEqual((await fs.stat(target)).mtimeMs, before.mtimeMs);
    const disabled = setResolvedAppEnabled({ existing: changed, appId: 'one', enabled: false });
    await writeAppsResolutionFileIfChanged({ rtwsRootAbs: rtws, file: disabled });
    assert.deepEqual(
      (await readAppResolution(rtws)).apps.find((entry) => entry.id === 'one'),
      { ...one, assignedPort: 43002, enabled: false },
    );
    const removed = removeResolvedApp({ existing: disabled, appId: 'one' });
    await writeAppsResolutionFileIfChanged({ rtwsRootAbs: rtws, file: removed });
    assert.deepEqual((await readAppResolution(rtws)).apps, [other]);
    assert.deepEqual(file, original);
  });
  console.log(
    'no-op mutations preserve disk bytes and timestamp; actual changes persist without losing other packages: passed',
  );
}
main().catch((error: unknown) => {
  console.error(error);
  process.exitCode = 1;
});

import assert from 'node:assert/strict';
import * as fs from 'node:fs/promises';
import path from 'node:path';
import YAML from 'yaml';

import { parseAppLockFile } from '../main/apps/app-lock-file';
import { loadAppsConfigurationFile } from '../main/apps/configuration-file';
import { readAppResolution, writeLocalApp } from './helpers/app-fixture';
import { runDomindsCli } from './helpers/cli-process';
import { semanticEvidenceCollector } from './helpers/semantic-evidence';
import { withTempRtws } from './kernel-driver/helpers';

const evidence = semanticEvidenceCollector('dominds-app-lock-');
async function main(): Promise<void> {
  await withTempRtws(async (rtws) => {
    const id = 'app_lock_test';
    await writeLocalApp(path.join(rtws, 'local-app'), id);
    const install = runDomindsCli(['install', 'local-app', '--local', '--enable'], rtws);
    assert.equal(install.status, 0);
    const target = path.join(rtws, '.minds', 'app-lock.yaml');
    const lockBytes = await fs.readFile(target);
    const parsed = parseAppLockFile(YAML.parse(lockBytes.toString()) as unknown, target);
    assert.ok(parsed.ok);
    assert.equal(parsed.file.apps.length, 1);
    assert.equal(parsed.file.apps[0].id, id);
    assert.deepEqual(parsed.file.apps[0].package, { name: id, version: '0.0.0' });
    const rootManifest = await fs.readFile(path.join(rtws, '.minds', 'app.yaml'));
    // An old explicit timestamp makes any rewrite observable without waiting on clock granularity.
    await fs.utimes(target, new Date('2000-01-01T00:00:00Z'), new Date('2000-01-01T00:00:00Z'));
    const oldMtime = (await fs.stat(target)).mtimeMs;
    for (const command of ['disable', 'enable'] as const) {
      const result = runDomindsCli([command, id], rtws);
      assert.equal(result.status, 0);
      const configuration = await loadAppsConfigurationFile({ rtwsRootAbs: rtws });
      assert.notEqual(configuration.kind, 'error');
      if (configuration.kind === 'error') throw new Error(configuration.errorText);
      assert.equal(configuration.file.disabledApps?.includes(id) ?? false, command === 'disable');
      const resolution = await readAppResolution(rtws);
      assert.equal(resolution.apps.find((entry) => entry.id === id)?.enabled, command === 'enable');
      assert.deepEqual(await fs.readFile(target), lockBytes);
      assert.equal((await fs.stat(target)).mtimeMs, oldMtime);
      assert.deepEqual(await fs.readFile(path.join(rtws, '.minds', 'app.yaml')), rootManifest);
      evidence.record({
        id: command,
        scenario: `A user ${command}s a locally installed compatibility package.`,
        businessValue:
          'The mutation receipt should explain the changed configuration and derived state without claiming to rewrite declaration or lock data.',
        context: {
          command,
          appId: id,
          effectiveEnabled: command === 'enable',
          lockUnchanged: true,
          manifestUnchanged: true,
        },
        reviewQuestions: [
          'Does the complete receipt agree with the actual change and unchanged declaration/lock state?',
          'Is its next-step guidance usable without presenting the retired App composition root as the destination architecture?',
        ],
        actualText: JSON.stringify(result, null, 2),
      });
    }
    evidence.record({
      id: 'install',
      scenario: 'A user installs an owned local compatibility package with --enable.',
      businessValue:
        'Explain the actual local install outcome and current configuration boundaries.',
      context: {
        appId: id,
        source: 'owned local package, no registry request',
        installStatus: install.status,
      },
      reviewQuestions: [
        'Does the actual receipt describe the completed local installation and its configuration boundaries accurately?',
      ],
      actualText: JSON.stringify(install, null, 2),
    });
  });
  await evidence.write();
  console.log(
    'real disable/enable update effective state while preserving declaration and lock bytes/timestamp after each command: passed',
  );
}
main().catch((error: unknown) => {
  console.error(error);
  process.exitCode = 1;
});

import assert from 'node:assert/strict';
import * as fs from 'node:fs/promises';
import net from 'node:net';
import path from 'node:path';

import { loadEnabledAppsSnapshot, materializeAppsResolution } from '../main/apps/enabled-apps';
import { writeAppsResolutionFile } from '../main/apps/resolution-file';
import {
  readAppResolution,
  resolvedApp,
  writeAppManifest,
  writeAppText,
  writeLocalApp,
} from './helpers/app-fixture';
import { semanticEvidenceCollector } from './helpers/semantic-evidence';
import { withTempRtws } from './kernel-driver/helpers';

const evidence = semanticEvidenceCollector('dominds-app-ports-');
async function main(): Promise<void> {
  await withTempRtws(async (rtws) => {
    const blocker = net.createServer();
    await new Promise<void>((resolve, reject) => {
      blocker.once('error', reject);
      blocker.listen(0, '127.0.0.1', resolve);
    });
    try {
      const address = blocker.address();
      assert.ok(address && typeof address === 'object');
      const conflictPort = address.port;
      const ids = ['app_port_a', 'app_port_b'];
      const packages = await Promise.all(
        ids.map((id) =>
          writeLocalApp(path.join(rtws, 'pkgs', id), id, { defaultPort: conflictPort }),
        ),
      );
      await writeAppManifest(rtws, 'rtws_root', ids);
      await writeAppText(
        path.join(rtws, '.apps', 'configuration.yaml'),
        'schemaVersion: 1\nresolutionStrategy:\n  order: [local]\n  localRoots: [pkgs]\n',
      );
      await writeAppsResolutionFile({
        rtwsRootAbs: rtws,
        file: {
          schemaVersion: 1,
          apps: packages.map((pkg) => ({
            ...resolvedApp(pkg, conflictPort),
            source: { kind: 'npx' as const, spec: `${pkg.appId}@0.0.0` },
          })),
        },
      });
      const snapshot = await loadEnabledAppsSnapshot({ rtwsRootAbs: rtws });
      assert.deepEqual(snapshot.enabledApps.map((app) => app.id).sort(), ids);
      const ports = snapshot.enabledApps.map((app) => app.runtimePort);
      assert.ok(
        ports.every((port) => typeof port === 'number' && port > 0 && port !== conflictPort),
      );
      assert.equal(new Set(ports).size, 2);
      const reassigned = snapshot.issues.filter(
        (issue) => issue.kind === 'assigned_port_reassigned',
      );
      assert.deepEqual(reassigned.map((issue) => issue.detail.appId).sort(), ids);
      const persisted = await readAppResolution(rtws);
      for (const app of snapshot.enabledApps) {
        const entry = persisted.apps.find((entry) => entry.id === app.id);
        assert.ok(entry);
        assert.equal(entry.assignedPort, app.runtimePort);
        assert.deepEqual(
          entry.installJson,
          packages.find((pkg) => pkg.appId === app.id),
        );
        const issue = reassigned.find((issue) => issue.detail.appId === app.id);
        assert.equal(issue?.detail.previousAssignedPort, conflictPort);
        assert.equal(issue?.detail.reassignedToPort, app.runtimePort);
      }
      evidence.record({
        id: 'reassigned',
        scenario:
          'Two cached local packages share one port which is also occupied by a real owned TCP listener.',
        businessValue: 'Operators can identify which package port changed and why.',
        context: {
          blockedPort: conflictPort,
          packages: ids.join(','),
          persistedPortsAgreeWithRuntime: true,
        },
        reviewQuestions: [
          'Do the complete warnings accurately identify the affected packages, old and new ports, and reason without suggesting the packages failed to resolve?',
        ],
        actualText: JSON.stringify(snapshot, null, 2),
      });
      const target = path.join(rtws, '.apps', 'resolution.yaml');
      await fs.utimes(target, new Date('2000-01-01T00:00:00Z'), new Date('2000-01-01T00:00:00Z'));
      const bytes = await fs.readFile(target);
      const mtime = (await fs.stat(target)).mtimeMs;
      const again = await materializeAppsResolution({ rtwsRootAbs: rtws });
      assert.equal(again.wroteResolutionFile, false);
      assert.deepEqual(again.resolved.issues, []);
      assert.deepEqual(again.resolved.resolutionFile, persisted);
      assert.deepEqual(await fs.readFile(target), bytes);
      assert.equal((await fs.stat(target)).mtimeMs, mtime);
      // A single cached port has no in-file duplicate: the real listener alone forces reassignment.
      await writeAppManifest(rtws, 'rtws_root', [ids[0]]);
      await writeAppsResolutionFile({
        rtwsRootAbs: rtws,
        file: { schemaVersion: 1, apps: [resolvedApp(packages[0], conflictPort)] },
      });
      const blocked = await loadEnabledAppsSnapshot({ rtwsRootAbs: rtws });
      assert.deepEqual(
        blocked.enabledApps.map((app) => app.id),
        [ids[0]],
      );
      assert.ok(
        typeof blocked.enabledApps[0].runtimePort === 'number' &&
          blocked.enabledApps[0].runtimePort > 0,
      );
      assert.notEqual(blocked.enabledApps[0].runtimePort, conflictPort);
      assert.equal(blocked.issues.length, 1);
      assert.equal(blocked.issues[0].kind, 'assigned_port_reassigned');
      assert.equal(blocked.issues[0].detail.reason, 'reassigned_from_existing_unbindable');
      assert.equal(
        (await readAppResolution(rtws)).apps[0].assignedPort,
        blocked.enabledApps[0].runtimePort,
      );
      evidence.record({
        id: 'occupied-only',
        scenario:
          'One cached frontend port is occupied by a real owned TCP listener; there is no other package to conflict with.',
        businessValue: 'The operator can distinguish an occupied port from a duplicate assignment.',
        context: { blockedPort: conflictPort, appId: ids[0], persistedPortsAgreeWithRuntime: true },
        reviewQuestions: [
          'Does the actual warning explain the port reassignment consistently with the single-package occupied-listener scenario?',
        ],
        actualText: JSON.stringify(blocked, null, 2),
      });
    } finally {
      await new Promise<void>((resolve, reject) =>
        blocker.close((error) => (error ? reject(error) : resolve())),
      );
    }
  });
  await evidence.write();
  console.log(
    'duplicate and occupied frontend ports are reassigned, persisted consistently and remain stable on reload: passed',
  );
}
main().catch((error: unknown) => {
  console.error(error);
  process.exitCode = 1;
});

import assert from 'node:assert/strict';
import * as fs from 'node:fs/promises';
import path from 'node:path';

import { loadEnabledAppsSnapshot } from '../main/apps/enabled-apps';
import { writeAppsResolutionFile } from '../main/apps/resolution-file';
import {
  readAppResolution,
  resolvedApp,
  writeAppManifest,
  writeAppText,
  writeLocalApp,
} from './helpers/app-fixture';
import { semanticEvidenceCollector } from './helpers/semantic-evidence';
import { withTempRtws } from './kernel-driver/helpers';

const evidence = semanticEvidenceCollector('dominds-app-effective-');
async function main(): Promise<void> {
  await withTempRtws(async (rtws) => {
    const ids = ['app_a', 'app_b'];
    const a = await writeLocalApp(path.join(rtws, 'dominds-apps', ids[0]), ids[0], {
      dependencies: [ids[1]],
      defaultPort: 0,
    });
    const b = await writeLocalApp(path.join(rtws, 'dominds-apps', ids[1]), ids[1], {
      defaultPort: 0,
    });
    await writeAppManifest(rtws, 'rtws_root', [ids[0]]);
    const configuration = path.join(rtws, '.apps', 'configuration.yaml');
    const healthyConfig =
      'schemaVersion: 1\nresolutionStrategy:\n  order: [local]\n  localRoots: [dominds-apps]\n';
    await writeAppText(configuration, healthyConfig);
    await writeAppsResolutionFile({
      rtwsRootAbs: rtws,
      file: { schemaVersion: 1, apps: [resolvedApp(a), resolvedApp(b)] },
    });
    const first = await loadEnabledAppsSnapshot({ rtwsRootAbs: rtws });
    assert.deepEqual(first.enabledApps.map((app) => app.id).sort(), ids);
    assert.deepEqual(first.issues, []);
    const before = await readAppResolution(rtws);
    const disabledConfig = healthyConfig + 'disabledApps: [app_b]\n';
    await writeAppText(configuration, disabledConfig);
    const disabled = await loadEnabledAppsSnapshot({ rtwsRootAbs: rtws });
    assert.deepEqual(disabled.enabledApps, []);
    const missing = disabled.issues.filter(
      (issue) => issue.kind === 'required_dependency_disabled',
    );
    assert.equal(missing.length, 1);
    assert.equal(missing[0].detail.appId, ids[1]);
    const affected = disabled.issues.filter(
      (issue) => issue.kind === 'app_effectively_disabled_due_to_required_dependency',
    );
    assert.equal(affected.length, 1);
    assert.equal(affected[0].detail.appId, ids[0]);
    assert.equal(affected[0].detail.dependencyId, ids[1]);
    assert.equal(affected[0].detail.dependencyState, 'disabled');
    assert.deepEqual(await readAppResolution(rtws), {
      ...before,
      apps: before.apps.map((app) => ({ ...app, enabled: false })),
    });
    assert.equal(await fs.readFile(configuration, 'utf8'), disabledConfig);
    evidence.record({
      id: 'required-dependency-disabled',
      scenario:
        'app_a requires app_b; disabling app_b makes both unavailable and writes both effective flags false while retaining package data and assigned ports.',
      businessValue:
        'Operators can identify the disabled dependency and why the parent cannot run.',
      context: {
        parent: ids[0],
        dependency: ids[1],
        effectiveApps: 0,
        packageDataAndPortsPreserved: true,
      },
      reviewQuestions: [
        'Do the complete diagnostics explain both the explicit dependency disable and its effect on the parent accurately?',
        'Do they avoid implying that rewriting the derived cache alone changes the declaration or configuration?',
      ],
      actualText: JSON.stringify(disabled, null, 2),
    });
    await writeAppText(configuration, healthyConfig);
    const recovered = await loadEnabledAppsSnapshot({ rtwsRootAbs: rtws });
    assert.deepEqual(recovered.enabledApps.map((app) => app.id).sort(), ids);
    assert.deepEqual(recovered.issues, []);
    assert.deepEqual(await readAppResolution(rtws), before);
    assert.equal(await fs.readFile(configuration, 'utf8'), healthyConfig);
  });
  await evidence.write();
  console.log(
    'required dependency disable and recovery persist effective flags without losing source, package data or ports: passed',
  );
}
main().catch((error: unknown) => {
  console.error(error);
  process.exitCode = 1;
});

import assert from 'node:assert/strict';
import path from 'node:path';

import { loadEnabledAppsSnapshot } from '../main/apps/enabled-apps';
import { reconcileAppsResolutionIssuesToProblems } from '../main/apps/problems';
import {
  clearProblems,
  getProblemsSnapshot,
  listProblems,
  removeProblem,
  removeProblemsByPrefix,
  upsertProblem,
} from '../main/problems';
import { writeAppManifest, writeAppText, writeLocalApp } from './helpers/app-fixture';
import { semanticEvidenceCollector } from './helpers/semantic-evidence';
import { withTempRtws } from './kernel-driver/helpers';

const evidence = semanticEvidenceCollector('dominds-app-problems-');
const prefix = 'apps/apps_resolution/';
const appProblems = () =>
  getProblemsSnapshot().problems.filter((problem) => problem.id.startsWith(prefix));
async function main(): Promise<void> {
  await withTempRtws(async (rtws) => {
    const id = 'missing_required_app';
    const unrelatedId = 'owned-unrelated-problem';
    removeProblemsByPrefix(prefix);
    upsertProblem({
      id: unrelatedId,
      kind: 'generic_problem',
      source: 'system',
      severity: 'warning',
      timestamp: new Date().toISOString(),
      message: 'unrelated-provided-data',
      detail: { text: 'unrelated-detail-data' },
    });
    const unrelated = listProblems({ problemId: unrelatedId });
    try {
      await writeAppManifest(rtws, 'rtws_root', [id]);
      const missing = await loadEnabledAppsSnapshot({ rtwsRootAbs: rtws });
      assert.deepEqual(missing.enabledApps, []);
      assert.equal(missing.issues.length, 1);
      assert.equal(missing.issues[0].kind, 'required_dependency_missing');
      assert.equal(missing.issues[0].detail.appId, id);
      reconcileAppsResolutionIssuesToProblems({ issues: missing.issues });
      const active = appProblems();
      assert.equal(active.length, 1);
      assert.equal(active[0].resolved, false);
      assert.equal(active[0].severity, missing.issues[0].severity);
      assert.equal(active[0].source, 'system');
      // Full message equality here protects actual forwarding fidelity, never its meaning.
      assert.equal(active[0].message, missing.issues[0].message);
      assert.equal(active[0].kind, 'generic_problem');
      if (active[0].kind !== 'generic_problem') throw new Error('Expected a generic app Problem');
      assert.deepEqual(JSON.parse(active[0].detail?.text ?? 'null'), missing.issues[0].detail);
      reconcileAppsResolutionIssuesToProblems({ issues: missing.issues });
      assert.deepEqual(
        appProblems().map((problem) => problem.id),
        active.map((problem) => problem.id),
      );
      evidence.record({
        id: 'missing',
        scenario:
          'A required local package is absent; native resolution issues are forwarded to the Problems store.',
        businessValue:
          'The user can identify the missing package and a concrete recovery location.',
        context: { appId: id, enabledPackages: 0, activeProblems: 1, noRegistryRequests: true },
        reviewQuestions: [
          'Do the actual issue, detail and Problems message agree on the missing package and provide useful recovery information?',
          'Does the guidance describe the current compatibility configuration without claiming the retired architecture is the new destination?',
        ],
        actualText: JSON.stringify({ snapshot: missing, problems: active }, null, 2),
      });
      // Resolve the actual cause, rather than manufacturing reconcile([]) as a healthy resolver.
      await writeLocalApp(path.join(rtws, 'dominds-apps', id), id);
      const healthy = await loadEnabledAppsSnapshot({ rtwsRootAbs: rtws });
      assert.deepEqual(
        healthy.enabledApps.map((app) => app.id),
        [id],
      );
      assert.deepEqual(healthy.issues, []);
      reconcileAppsResolutionIssuesToProblems({ issues: healthy.issues });
      const resolved = appProblems();
      assert.deepEqual(
        resolved.map((problem) => problem.id),
        active.map((problem) => problem.id),
      );
      assert.ok(
        resolved.every(
          (problem) =>
            problem.resolved &&
            typeof problem.resolvedAt === 'string' &&
            Number.isFinite(Date.parse(problem.resolvedAt)),
        ),
      );
      assert.equal(
        listProblems({ resolved: false }).some((problem) => problem.id === active[0].id),
        false,
      );
      assert.equal(clearProblems({ problemId: active[0].id, resolved: true }), 1);
      assert.deepEqual(appProblems(), []);
      assert.deepEqual(listProblems({ problemId: unrelatedId }), unrelated);
      await writeAppText(
        path.join(rtws, '.apps', 'configuration.yaml'),
        `schemaVersion: 1\ndisabledApps: [${id}]\n`,
      );
      const disabled = await loadEnabledAppsSnapshot({ rtwsRootAbs: rtws });
      assert.deepEqual(disabled.enabledApps, []);
      assert.equal(disabled.issues.length, 1);
      assert.equal(disabled.issues[0].kind, 'required_dependency_disabled');
      reconcileAppsResolutionIssuesToProblems({ issues: disabled.issues });
      const disabledProblems = appProblems();
      assert.equal(disabledProblems.length, 1);
      assert.notEqual(disabledProblems[0].id, active[0].id);
      assert.equal(disabledProblems[0].resolved, false);
      assert.equal(disabledProblems[0].severity, disabled.issues[0].severity);
      assert.equal(disabledProblems[0].source, 'system');
      assert.equal(disabledProblems[0].message, disabled.issues[0].message);
      assert.equal(disabledProblems[0].kind, 'generic_problem');
      if (disabledProblems[0].kind !== 'generic_problem')
        throw new Error('Expected a generic app Problem');
      assert.deepEqual(
        JSON.parse(disabledProblems[0].detail?.text ?? 'null'),
        disabled.issues[0].detail,
      );
      assert.deepEqual(listProblems({ problemId: unrelatedId }), unrelated);
      evidence.record({
        id: 'disabled',
        scenario:
          'The package now exists, but configuration explicitly disables it while the root still requires it.',
        businessValue:
          'The user can distinguish a missing package from a disabled one and use the correct recovery path.',
        context: {
          appId: id,
          enabledPackages: 0,
          activeProblems: 1,
          oldMissingProblemCleared: true,
        },
        reviewQuestions: [
          'Does the complete issue/Problems text correctly describe an installed but disabled required package?',
          'Is the proposed configuration location consistent with the actual scenario?',
        ],
        actualText: JSON.stringify({ snapshot: disabled, problems: disabledProblems }, null, 2),
      });
    } finally {
      removeProblemsByPrefix(prefix);
      removeProblem(unrelatedId);
    }
  });
  await evidence.write();
  console.log(
    'real missing/disabled package issues preserve data, resolve after actual repair and clear without touching unrelated Problems: passed',
  );
}
main().catch((error: unknown) => {
  console.error(error);
  process.exitCode = 1;
});

import assert from 'node:assert/strict';
import * as fs from 'node:fs/promises';
import path from 'node:path';

import { loadEnabledAppTeammates } from '../main/apps/teammates';
import { writeAppManifest, writeAppText, writeLocalApp } from './helpers/app-fixture';
import { withTempRtws } from './kernel-driver/helpers';

async function main(): Promise<void> {
  await withTempRtws(async (rtws) => {
    const common = path.join(rtws, 'dominds-apps', 'common_agents');
    const mid = path.join(rtws, 'dominds-apps', 'mid_agents');
    const outer = path.join(rtws, 'dominds-apps', 'outer_agents');
    await writeAppManifest(rtws, 'rtws_root', ['outer_agents']);
    await writeLocalApp(common, 'common_agents', {
      packageName: 'app-common-agents',
      teammatesYamlRelPath: 'team.yaml',
    });
    await writeLocalApp(mid, 'mid_agents', {
      packageName: 'app-mid-agents',
      dependencies: ['common_agents', 'outer_agents'],
    });
    await writeLocalApp(outer, 'outer_agents', {
      packageName: 'app-outer-agents',
      dependencies: ['mid_agents'],
    });
    const defaults = path.join(common, 'team.yaml');
    const middleOverride = path.join(mid, '.apps', 'override', 'common_agents', 'team.yaml');
    const outerOverride = path.join(outer, '.apps', 'override', 'common_agents', 'team.yaml');
    const rtwsOverride = path.join(rtws, '.apps', 'override', 'common_agents', 'team.yaml');
    const values = {
      default: {
        name: 'ScribeFromDefault',
        description: 'given-default-description',
        toolsets: ['ws_read'],
      },
      mid: {
        name: 'ScribeFromMidOverride',
        description: 'given-mid-description',
        toolsets: ['ws_read'],
      },
      outer: {
        name: 'ScribeFromOuterOverride',
        description: 'given-outer-description',
        toolsets: ['personal_memory'],
      },
      rtws: {
        name: 'ScribeFromRtwsOverride',
        description: 'given-rtws-description',
        toolsets: ['ws_mod'],
      },
    };
    for (const [file, data] of [
      [defaults, values.default],
      [middleOverride, values.mid],
      [outerOverride, values.outer],
    ] as const) {
      // JSON is valid YAML; all fields below are opaque supplied member data.
      await writeAppText(file, JSON.stringify({ members: { scribe: data } }));
    }
    const expect = async (value: typeof values.default) =>
      assert.deepEqual(await loadEnabledAppTeammates({ rtwsRootAbs: rtws }), [
        { appId: 'common_agents', members: { scribe: value } },
      ]);
    // The mid/outer cycle must terminate; outside integrator overrides beat inside ones.
    await expect(values.outer);
    await writeAppText(rtwsOverride, JSON.stringify({ members: { scribe: values.rtws } }));
    await expect(values.rtws);
    await fs.rm(rtwsOverride);
    await fs.rm(outerOverride);
    await expect(values.mid);
    await fs.rm(middleOverride);
    await expect(values.default);
  });
  console.log(
    'cyclic package graph terminates; rtws, outer, inner and default member payloads follow precedence: passed',
  );
}
main().catch((error: unknown) => {
  console.error(error);
  process.exitCode = 1;
});

import assert from 'node:assert/strict';
import * as fs from 'node:fs/promises';
import net from 'node:net';
import path from 'node:path';

import { loadEnabledAppsSnapshot, materializeAppsResolution } from '../main/apps/enabled-apps';
import { readAppResolution, writeAppManifest, writeLocalApp } from './helpers/app-fixture';
import { withTempRtws } from './kernel-driver/helpers';

async function main(): Promise<void> {
  await withTempRtws(async (rtws) => {
    const id = 'example_app';
    // No resolutionStrategy configuration or fixture ENV variables: use the native local default.
    await fs.rm(path.join(rtws, '.apps', 'configuration.yaml'), { force: true });
    await writeAppManifest(rtws, 'rtws_root', [id]);
    const packageRoot = path.join(rtws, 'dominds-apps', id);
    const listener = net.createServer();
    await new Promise<void>((resolve, reject) => {
      listener.once('error', reject);
      listener.listen(0, '127.0.0.1', resolve);
    });
    const address = listener.address();
    assert.ok(address && typeof address === 'object');
    const preferredPort = address.port;
    await new Promise<void>((resolve, reject) =>
      listener.close((error) => (error ? reject(error) : resolve())),
    );
    const supplied = await writeLocalApp(packageRoot, id, { defaultPort: preferredPort });
    const snapshot = await loadEnabledAppsSnapshot({ rtwsRootAbs: rtws });
    assert.deepEqual(
